import{z as E,x as m,o as A,c as p,q as o,j as s,D as n,d as r,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"AuT：AED 音频 Transformer 编码器","description":"","frontmatter":{"title":"AuT：AED 音频 Transformer 编码器","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-asr-aut.md","filePath":"llm/qwen3-asr-aut.md","lastUpdated":1791063341000}'),d={name:"llm/qwen3-asr-aut.md"};function u(B,a,T,L,h,D){const t=m("Mermaid");return A(),p("div",null,[a[2]||(a[2]=o('<h1 id="aut-aed-音频-transformer-编码器" tabindex="-1">AuT：AED 音频 Transformer 编码器 <a class="header-anchor" href="#aut-aed-音频-transformer-编码器" aria-label="Permalink to &quot;AuT：AED 音频 Transformer 编码器&quot;">​</a></h1><div class="epigraph"><p>AuT 是基于注意力编码器–解码器的 ASR 模型，对 128 维 Fbank 做 8 倍下采样，得到 12.5 Hz 的音频编码器。</p><footer>—— Qwen Team，Qwen3-ASR Technical Report，arXiv:2601.21337</footer></div><p>把波形送进 LLM 之前，必须有一个音频前端给出时间上可承受的表示。Qwen3-Omni 与 Qwen3-ASR 把这个前端叫做 AuT（Audio Transformer）。它不是 LLM 内部的一层自注意力，而是独立预训练的注意力编码器–解码器（AED）风格音频模型：先按 ASR/音频理解目标把 Fbank 编成隐状态，再（在 Omni/ASR 里）丢掉或不用其解码器，只把编码器输出经 projector 交给 Qwen3。AuT 的职责是给 LLM 提供音频表示，而不是在部署时自己贪心出字。本篇讲清 AED 编码器作为特征器的几何：维数、下采样、窗口注意力，以及它与 Whisper 编码器、纯 CTC 前端的差别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>16 kHz 波形经 25 ms 窗、10 ms 跳步得到约 100 Hz 的 128 维 Fbank。若每帧直接当一个 LLM token，一分钟 6000 步，加上文本，上下文与 KV 缓存都偏长，且相邻帧高度冗余。前端必须沿时间压缩，并把通道映到 LLM 隐藏维。压缩太狠，辅音与短停顿消失；压缩太少，LLM 做不成实时。</p><p>Whisper 编码器是成熟选择，Qwen2.5-Omni 仍走类似路线。Qwen3-Omni 认为通用音频表示应在更大规模监督上从零训：约 2000 万小时，中英伪标注 ASR 为主、兼其他语种与音频理解。Qwen3-ASR 里 AuT 还要再适应动态窗口，以便同一套权重既流式又离线。需要的不是「又一个 Conformer」，而是明确的 token 率与窗口契约，好让 FlashAttention 和 projector 设计有数可算。</p><h3 id="aed-作为表示学习器" tabindex="-1">AED 作为表示学习器 <a class="header-anchor" href="#aed-作为表示学习器" aria-label="Permalink to &quot;AED 作为表示学习器&quot;">​</a></h3><p>AED 训练时，解码器用交叉注意力读编码器记忆并生成词。编码器因此被要求保存可被注意力检索的内容，而不是只优化帧级分类。训完之后，部署可以只保留编码器：记忆已经对「会被问到的词」友好。这与仅 CTC 预训练的编码器不同——CTC 编码器对折叠路径友好，对 LLM 的软前缀不一定最优。AuT 报告中的图示包含编码器自注意、Conv2D 下采样与解码器交叉注意；ASR 推理图则只接「预训练 AuT 编码器 → Qwen3 LM」。</p><p><span class="marginnote">AED 里的 D（解码器）在特征器阶段是训练脚手架。Qwen3-ASR 发布件用编码器输出，不再用 AuT 自己的词面解码器出最终转写。若把 AuT 整模型当 ASR 用，就退回传统 AED，丢掉 LALM 的 LLM 先验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Fbank 128 维、约 100 Hz，经 Conv2D 块 8 倍下采样，时间率变为 \\(100/8=12.5\\) Hz，即每帧约 80 ms。这与 Omni 文本里「每帧对应约 80 ms」一致。Qwen3-ASR-1.7B 的 AuT 约 300M 参数、隐藏维 1024；0.6B 型号的 AuT 约 180M、隐藏维 896。Omni 基座里的 AuT 约 650M，规格更大，因任务更通用。ASR 用的 AuT 与 Omni 分开预训练：ASR 报告写约 4000 万小时伪标注 ASR；Omni 报告写 2000 万小时监督音频且含理解任务。两者同名异构，对接时靠 projector 把隐藏维对齐到 Qwen3。</p><p>注意力使用动态 FlashAttention 窗口，查询跨度从约 1 秒到 8 秒。短窗服务流式块；长窗服务离线整句。训练时随机或按课程抽窗口，推理时可固定 8 秒窗口做离线，或短窗做流式。于是同一编码器权重覆盖两种延迟曲线，而不必训两个前端。</p>',12)),(A(),s(l,null,{default:n(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20FB%5B%22Fbank%20128%20%E7%BB%B4%20100Hz%22%5D%20--%3E%20C%5B%22Conv2D%208%20%E5%80%8D%E4%B8%8B%E9%87%87%E6%A0%B7%22%5D%0A%20%20C%20--%3E%20E%5B%22Transformer%20%E7%BC%96%E7%A0%81%E5%99%A8%2012.5Hz%22%5D%0A%20%20E%20--%3E%20D%5B%22AED%20%E8%A7%A3%E7%A0%81%E5%99%A8%20%E4%BB%85%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20E%20--%3E%20PR%5B%22projector%22%5D%0A%20%20PR%20--%3E%20Q%5B%22Qwen3%20LLM%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"从-aed-损失到-llm-前缀",tabindex:"-1"},[r("从 AED 损失到 LLM 前缀 "),e("a",{class:"header-anchor",href:"#从-aed-损失到-llm-前缀","aria-label":'Permalink to "从 AED 损失到 LLM 前缀"'},"​")],-1)),a[4]||(a[4]=e("p",null,"预训练损失是 AED 的交叉熵（加可能的理解任务）。编码器梯度来自「解码器能否听见正确的词」。进入 LALM 后，损失变成 Qwen3 的转写交叉熵，梯度经 projector 回流编码器（是否冻结取决于阶段）。Omni 的 S1 阶段曾冻结 LLM、先训 adapter 再训编码器，避免编码器去补偿被冻住的 LLM。ASR 后训练则在已对齐的空间上做风格迁移。数学上，encoder 输出 \\(H\\in\\mathbb{R}^{T\\times d_{\\mathrm{aut}}}\\)，\\(T=\\lfloor L_{\\mathrm{sec}}\\times 12.5\\rfloor\\)，",-1)),a[5]||(a[5]=r(" \\[Z = HW_p,\\qquad Z\\in\\mathbb{R}^{T\\times d_{\\mathrm{llm}}}, \\]",-1)),a[6]||(a[6]=e("p",null,"\\(Z\\) 作为前缀（或交叉注意记忆）进入 LLM。\\(W_p\\) 即学习型 projector，另文展开；这里只需知道 AuT 的 \\(d_{\\mathrm{aut}}\\) 不必等于 \\(d_{\\mathrm{llm}}\\)。",-1)),a[7]||(a[7]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[8]||(a[8]=e("p",null,"8 倍下采样把 10 ms 级细节交给卷积局部感受野，Transformer 层在 80 ms 网格上做中程依赖。12.5 Hz 与 Omni 输出 codec 同数量级，音画时间 ID 好对齐，也让一分钟音频大约 750 个音频 token，LLM 可接受。窗口注意力把自注意从全长音频的二次成本改成窗口内二次：8 秒窗约 100 个 token 量级，流式时更短。动态窗的代价是长短依赖不稳定——1 秒窗看不见跨秒韵律，8 秒窗延迟高。训练覆盖区间，是让同一套参数在两种掩码下都能给出可用表示，而不是推理时自适应到任意窗而不掉点。",-1)),a[9]||(a[9]=e("p",null,"同一分钟音频在不同窗口宽度下的账可以摊开算：窗口越窄，窗内比较次数越少、出字越快，但看不见窗外的韵律；窗口越宽则相反。这就是动态窗在取舍什么：",-1)),(A(),s(l,null,{default:n(()=>[i(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%80%E5%88%86%E9%92%9F%E9%9F%B3%E9%A2%91%20%E7%BA%A6%20750%20%E4%B8%AA%E9%9F%B3%E9%A2%91%20token%22%5D%20--%3E%20W1%5B%221%20%E7%A7%92%E7%AA%97%20%E7%BA%A6%2012%20%E5%B8%A7%22%5D%0A%20%20IN%20--%3E%20W8%5B%228%20%E7%A7%92%E7%AA%97%20%E7%BA%A6%20100%20%E5%B8%A7%22%5D%0A%20%20W1%20--%3E%20C1%5B%22%E7%AA%97%E5%86%85%E7%BA%A6%2012x12%20%E6%AC%A1%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%AF%94%E8%BE%83%22%5D%0A%20%20W8%20--%3E%20C8%5B%22%E7%AA%97%E5%86%85%E7%BA%A6%20100x100%20%E6%AC%A1%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%AF%94%E8%BE%83%22%5D%0A%20%20C1%20--%3E%20S%5B%22%E5%BB%B6%E8%BF%9F%E4%BD%8E%20%E9%80%82%E5%90%88%E6%B5%81%E5%BC%8F%E5%AE%9E%E6%97%B6%E5%87%BA%E5%AD%97%22%5D%0A%20%20C8%20--%3E%20Q%5B%22%E7%9C%8B%E5%BE%97%E8%BF%9C%20%E9%80%82%E5%90%88%E7%A6%BB%E7%BA%BF%E6%95%B4%E5%8F%A5%E8%B4%A8%E9%87%8F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[10]||(a[10]=o('<p>AED 预训练让键值空间对语言查询可检索：解码器曾用文本状态去点音频记忆。LLM 的 projector 查询几何不同，但「内容可寻址的时间块」这一归纳偏置被保留。纯卷积下采样没有这种可检索记忆，要把全部压缩交给 LLM，12.5 Hz 可能不够用。</p><p><span class="marginnote">直觉类比：AED 预训练像让学生（解码器）对着老师的板书（编码器记忆）答题，板书因此被迫写得「可被检索」；毕业上岗时只带走写板书的能力（编码器），答题生成文字则交给更大的 LLM。</span></p><p><span class="marginnote">数字实例：12.5 Hz 意味着一分钟音频约 750 帧，而一分钟正常语速的话转写成文字大约也就几百个 token——把音频压到与它要输出的文字差不多长，正是「12.5 Hz 够用」的直觉来源。</span></p><p><span class="marginnote">Conv2D 的 8 倍是时间（及可能的频带）下采样设计，不是把 128 维压成 16 维。通道维由后续线性层和隐藏宽 896/1024 承担。混淆「时间 8×」与「特征 8×」会算错 token 率。</span></p><h3 id="与-whisper-编码器替换的意义" tabindex="-1">与 Whisper 编码器替换的意义 <a class="header-anchor" href="#与-whisper-编码器替换的意义" aria-label="Permalink to &quot;与 Whisper 编码器替换的意义&quot;">​</a></h3><p>Whisper 编码器在多语 ASR 上强，但对非语音理解、超长窗口与 Qwen 数据分布未必最优。从零训 AuT 可以用伪标注规模（千万小时级）覆盖中文方言与噪声，并用动态窗专门为流式服务。替换的代价是生态：不再能直接加载 Whisper 权重。Qwen3 选择在 Omni 与 ASR 两篇报告里把 AuT 写成一等模块，等于把音频前端从「借用 ASR 名模型」改成「自家表示学习器」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>12.5 Hz 对精细时间戳不够。强制对齐、字幕打轴要另模型，不能从 AuT 帧边界直接当字边界。极度短指令（百毫秒）可能只覆盖一两帧，表示方差大，依赖 LLM 先验。重叠说话人在 80 ms 块内混叠，AuT 不会神奇分离。</p><p>ASR 的 180M/300M 与 Omni 的 650M 不可互换权重而不过 projector。微调时若只训 LLM、冻 AuT，省算力但域外声学适应慢；若大步训 AuT，可能破坏与 LLM 已对齐的几何。动态窗在实现上依赖注意力掩码正确：漏掩未来帧会在流式评测中作弊。</p><p><span class="marginnote">为什么重要：微调时动不动 AuT 是真金白银的取舍——大学习率去训 AuT，等于把编码器已对齐到 LLM 的「接口几何」揉皱了，转写质量可能不升反降；工程上常见做法是先冻结 AuT 只调 LLM，确认真是声学域不匹配后，再用小步长解冻。</span></p><p><span class="marginnote">后续条目会分别写 128 维 Fbank、12.5 Hz、1s–8s 窗口与分块 Conv2D。本篇只定位 AuT：AED 训练出来的、给 LLM 用的音频 Transformer 编码器。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AuT 是 AED 风格的音频 Transformer：用编码器–解码器目标预训练，部署时把编码器表示交给 LLM。</li><li>128 维 Fbank 经 Conv2D 8× 下采样得到 12.5 Hz（约 80 ms）token，供 projector 对齐 Qwen3。</li><li>动态 FlashAttention 窗口 1s–8s 统一流式与离线；Omni 中约 650M，ASR 中约 180M/300M，分开预训练。</li><li>它替换 Whisper 式借用编码器，为大规模伪标注与长音频窗口服务，但不提供逐字时间戳。</li><li>AED 解码器是训练脚手架；最终转写由 LALM 的 Qwen3 头生成。</li><li>出处：Shi 等，Qwen3-ASR Technical Report，arXiv:2601.21337（2026 年 1 月）；Xu 等，Qwen3-Omni Technical Report，arXiv:2509.17765，其中 §2.2 Audio Transformer (AuT)。</li></ul>',13))])}const S=E(d,[["render",u]]);export{M as __pageData,S as default};
